        ['nama' => 'Master Document', 'cat' => 'tesis', 'desc' => 'An old feature that gathers subdocuments in Outline view. Avoid it for a thesis.', 'langkah' => 'View → Outline → Outlining → Show Document → Insert.', 'tip' => 'For a thesis, a single file with styles and the Navigation Pane is safer. Combine chapters with Text from File.', 'awas' => 'A document with subdocuments cannot be co-authored, and subdocument links break easily when files move.'],
        ['nama' => 'Always Create Backup Copy', 'cat' => 'tesis', 'desc' => 'Word keeps a copy of the previous version every time you save.', 'langkah' => 'File → Options → Advanced → Save → Always create backup copy.', 'tip' => 'The copy is named "Backup of …" with the .wbk extension, in the same folder.'],

        // === REVIEW ===
        ['nama' => 'Track Changes', 'cat' => 'semakan', 'popular' => true, 'desc' => 'Record every edit so it can be accepted or rejected.', 'langkah' => 'Review → Track Changes. To accept: Review → Accept or Accept All Changes.', 'pintasan' => 'Ctrl+Shift+E'],
        ['nama' => 'Comments', 'cat' => 'semakan', 'desc' => 'Comments in the margin that leave the text unchanged.', 'langkah' => 'Select text → Review → New Comment.', 'pintasan' => 'Ctrl+Alt+M'],
        ['nama' => 'Compare', 'cat' => 'semakan', 'desc' => 'Compare two versions of a document and see the differences.', 'langkah' => 'Review → Compare → Compare → choose the original and the revised document.'],
        ['nama' => 'Editor', 'cat' => 'semakan', 'desc' => 'Check spelling and grammar.', 'langkah' => 'Review → Editor (or Spelling & Grammar). Language: Review → Language → Set Proofing Language.', 'pintasan' => 'F7', 'tip' => 'For a document in Malay, set the proofing language to Malay so that not every word gets a red underline.'],
        ['nama' => 'Word Count', 'cat' => 'semakan', 'desc' => 'Counts of words, characters, and paragraphs.', 'langkah' => 'Review → Word Count, or click the word count in the status bar.', 'pintasan' => 'Ctrl+Shift+G'],
        ['nama' => 'Display for Review', 'cat' => 'semakan', 'desc' => 'Choose how much tracked markup is shown: Simple Markup, All Markup, No Markup, or Original.', 'langkah' => 'Review → Display for Review → choose a view.', 'tip' => 'All Markup shows every edit in the text. No Markup shows how the document looks if every change is accepted.', 'awas' => 'No Markup only hides the marks. The changes stay in the file until they are accepted or rejected.'],
        ['nama' => 'Accept and Move to Next', 'cat' => 'semakan', 'desc' => 'Review changes one at a time and decide whether each one stays.', 'langkah' => 'Review → Next → Accept (arrow) → Accept and Move to Next, or Reject → Reject and Move to Next.', 'tip' => 'Use Accept All Changes only after every change has been read.'],
        ['nama' => 'Lock Tracking', 'cat' => 'semakan', 'desc' => 'Stop others from turning off Track Changes without a password.', 'langkah' => 'Review → Track Changes (arrow) → Lock Tracking → type the password twice → OK.', 'tip' => 'Useful when a draft goes to a supervisor or group members, so that every edit is recorded.'],
        ['nama' => 'Reviewing Pane', 'cat' => 'semakan', 'desc' => 'A list of every change and comment in one pane, with a count.', 'langkah' => 'Review → Reviewing Pane → Reviewing Pane Vertical or Horizontal.', 'tip' => 'The revision count at the top of the pane helps confirm that no change is left before the document is sent.'],
        ['nama' => 'Delete All Comments', 'cat' => 'semakan', 'desc' => 'Remove every comment at once when the review is finished.', 'langkah' => 'Review → Delete (arrow) → Delete All Comments in Document.', 'awas' => 'Save a copy of the reviewed version first. Deleted comments cannot be restored after the file is closed.'],
        ['nama' => 'Combine', 'cat' => 'semakan', 'desc' => 'Gather the edits of several reviewers from separate copies into one document.', 'langkah' => 'Review → Compare → Combine → choose the original and the revised document → OK. Repeat for each reviewer.', 'awas' => 'Compare shows the differences between two versions. Combine gathers the edits of several people. Pick the right one before you start.'],

        // === MAIL MERGE ===
        ['nama' => 'Mail Merge: Letters', 'cat' => 'mel', 'popular' => true, 'desc' => 'One letter for many recipients, with names and addresses taken from an Excel list.', 'langkah' => 'Mailings → Start Mail Merge → Letters → Select Recipients → Use an Existing List (the Excel file) → Insert Merge Field → Preview Results → Finish & Merge.', 'tip' => 'The first row in Excel must hold the column headings (Name, Address, and so on). Leave no blank rows.'],
        ['nama' => 'Mail Merge: Labels', 'cat' => 'mel', 'desc' => 'Print address labels or name tags from a list.', 'langkah' => 'Mailings → Start Mail Merge → Labels → choose the label vendor and size → Select Recipients → Update Labels → Finish & Merge.'],
        ['nama' => 'Mail Merge: Envelopes', 'cat' => 'mel', 'desc' => 'Print recipient addresses directly on envelopes.', 'langkah' => 'Mailings → Start Mail Merge → Envelopes → Envelope Options (envelope size) → Select Recipients → Address Block → Finish & Merge.', 'tip' => 'Print one test envelope first to check the printer feed direction.'],
        ['nama' => 'Mail Merge: E-mail Messages', 'cat' => 'mel', 'desc' => 'A personal email to each recipient, sent from Word through Outlook.', 'langkah' => 'Mailings → Start Mail Merge → E-mail Messages → Select Recipients → Insert Merge Field → Finish & Merge → Send E-mail Messages → To (email column), Subject line, Mail format.', 'awas' => 'Each recipient gets a separate email. You cannot add CC, BCC, or attachments. Links are allowed.'],
        ['nama' => 'Edit Recipient List', 'cat' => 'mel', 'desc' => 'Select, sort, and filter recipients before merging.', 'langkah' => 'Mailings → Edit Recipient List → clear the check box for recipients you do not need, or use Sort and Filter.', 'tip' => 'Filter supports conditions such as Equal to, Is blank, and Contains. Sort works on up to three levels.'],
        ['nama' => 'Rules: If...Then...Else', 'cat' => 'mel', 'desc' => 'Different text based on a value in the list, for example "Mr" or "Ms" based on a Gender column.', 'langkah' => 'Place the cursor → Mailings → Rules → If...Then...Else → Field name, Comparison, Compare to → fill in the text for true and false → OK.'],
        ['nama' => 'Rules: Skip Record If', 'cat' => 'mel', 'desc' => 'Leave out recipients that meet a condition, for example students who have already paid.', 'langkah' => 'Mailings → Rules → Skip Record If → choose the field, condition, and value → OK.', 'tip' => 'Edit Recipient List → Filter gives the same result and is easier to check later.'],
        ['nama' => 'Preview Results', 'cat' => 'mel', 'desc' => 'See the document with real recipient data before merging.', 'langkah' => 'Mailings → Preview Results → Next Record or Previous Record. Find Recipient to locate a specific name.', 'pintasan' => 'Alt+Shift+K', 'tip' => 'Check the records with the longest name or address. That is where the layout usually breaks.'],
        ['nama' => 'Edit Individual Documents', 'cat' => 'mel', 'desc' => 'Merge into a new document so that every letter can be checked before printing.', 'langkah' => 'Mailings → Finish & Merge → Edit Individual Documents → All → OK.', 'pintasan' => 'Alt+Shift+N', 'awas' => 'The new document is no longer linked to the list. Fix the data in Excel and merge again instead of editing letters one by one.'],

        // === TEMPLATES AND FORMS ===
        ['nama' => 'Word Template (.dotx)', 'cat' => 'templat', 'desc' => 'Save formatting, styles, and fixed text as a template for new documents.', 'langkah' => 'File → Save As → Save as type: Word Template (*.dotx).', 'tip' => 'A template that contains macros is saved as .dotm.', 'awas' => 'Double-clicking a .dotx file opens a new document based on it. To edit the template itself, right-click the file → Open.'],
        ['nama' => 'Personal Templates', 'cat' => 'templat', 'desc' => 'Show your own templates in File → New.', 'langkah' => 'File → Options → Save → Default personal templates location → type the template folder path → OK. Then File → New → Personal.'],
        ['nama' => 'Save Selection to Quick Part Gallery', 'cat' => 'templat', 'desc' => 'Save a block of text you reuse, for example a signature block or a thesis declaration page.', 'langkah' => 'Select the text → Insert → Quick Parts → Save Selection to Quick Part Gallery → name it → OK.', 'pintasan' => 'Alt+F3', 'tip' => 'Include the paragraph mark ¶ in the selection so that paragraph formatting is saved too.'],
        ['nama' => 'AutoText', 'cat' => 'templat', 'desc' => 'Insert a saved block of text by typing the first few letters of its name.', 'langkah' => 'Save: select the text → Insert → Quick Parts → AutoText → Save Selection to AutoText Gallery. Insert: type the start of the name → Enter when the ScreenTip appears.'],
        ['nama' => 'Building Blocks Organizer', 'cat' => 'templat', 'desc' => 'A list of every saved block: edit properties, delete, or insert.', 'langkah' => 'Insert → Quick Parts → Building Blocks Organizer.', 'awas' => 'Blocks are stored in a template file. When Word asks on exit whether to save changes to the template, choose Save so the blocks are kept.'],
        ['nama' => 'Developer Tab', 'cat' => 'templat', 'desc' => 'The tab for content controls, macros, and Design Mode. It is hidden by default.', 'langkah' => 'File → Options → Customize Ribbon → select Developer in the right-hand list → OK.'],
        ['nama' => 'Content Controls', 'cat' => 'templat', 'desc' => 'Fill-in areas in a form: text, Drop-Down lists, Date Picker, and Check Box.', 'langkah' => 'Developer → Controls → choose a control, for example Plain Text Content Control or Date Picker Content Control.', 'tip' => 'To change the placeholder text in a control: Developer → Design Mode → type the text → turn off Design Mode.'],
        ['nama' => 'Content Control Properties', 'cat' => 'templat', 'desc' => 'The title, list choices, and locks for a control.', 'langkah' => 'Select the control → Developer → Properties → Title, Add (Drop-Down choices), Content control cannot be deleted → OK.'],
        ['nama' => 'Restrict Editing: Filling in Forms', 'cat' => 'templat', 'desc' => 'A form that allows only the controls to be filled in. Other text is locked.', 'langkah' => 'Review → Restrict Editing → Allow only this type of editing → Filling in forms → Yes, Start Enforcing Protection → password (optional).', 'awas' => 'A Restrict Editing password does not encrypt the file. It stops ordinary editing, not someone determined to get around it.'],

        // === SAVE AND SHARE ===
        ['nama' => 'Save as PDF', 'cat' => 'fail', 'popular' => true, 'desc' => 'A final document whose layout does not change on another computer.', 'langkah' => 'File → Save As → choose PDF, or File → Export → Create PDF/XPS.', 'pintasan' => 'F12 (Save As)'],
        ['nama' => 'AutoSave & Version History', 'cat' => 'fail', 'desc' => 'Save automatically and restore earlier versions.', 'langkah' => 'Save the file to OneDrive → the AutoSave switch at the top left. Earlier versions: File → Info → Version History.'],
        ['nama' => 'Inspect Document', 'cat' => 'fail', 'desc' => 'Remove comments, tracked changes, and hidden personal information before you send a document.', 'langkah' => 'File → Info → Check for Issues → Inspect Document.'],
        ['nama' => 'Restrict Editing', 'cat' => 'fail', 'desc' => 'Limit editing, for example a form that can only be filled in.', 'langkah' => 'Review → Restrict Editing.'],
        ['nama' => 'PDF: Create Bookmarks', 'cat' => 'fail', 'desc' => 'A PDF with bookmarks taken from headings, so readers can jump to a chapter.', 'langkah' => 'File → Save As → PDF → Options → Create bookmarks using: Headings → OK → Save.', 'awas' => 'Headings must use a Heading style. Text that is only made bold does not become a bookmark.'],
        ['nama' => 'PDF/A', 'cat' => 'fail', 'desc' => 'A PDF for long-term archiving. University thesis repositories often require it.', 'langkah' => 'File → Save As → PDF → Options → ISO 19005-1 compliant (PDF/A) → OK → Save.', 'tip' => 'Check your university library requirements before submitting the final version.'],
        ['nama' => 'PDF: Minimum Size', 'cat' => 'fail', 'desc' => 'A smaller PDF for email or portals that limit file size.', 'langkah' => 'File → Save As → PDF → Optimize for: Minimum size (publishing online) → Save.', 'awas' => 'Pictures become less sharp. For a printed copy, choose Standard (publishing online and printing).'],
        ['nama' => 'Embed Fonts', 'cat' => 'fail', 'desc' => 'Carry fonts inside the file so the document looks the same on a computer that lacks them.', 'langkah' => 'File → Options → Save → Embed fonts in the file.', 'tip' => 'Select Do not embed common system fonts to keep the file smaller.'],
        ['nama' => 'Mark as Final', 'cat' => 'fail', 'desc' => 'Mark the document as the final version. It opens read-only.', 'langkah' => 'File → Info → Protect Document → Mark as Final.', 'awas' => 'Anyone can click Edit Anyway. It is a signal to readers, not protection.'],
        ['nama' => 'Encrypt with Password', 'cat' => 'fail', 'desc' => 'A password that must be entered to open the document.', 'langkah' => 'File → Info → Protect Document → Encrypt with Password → type the password → type it again → OK.', 'awas' => 'Word cannot recover a lost password. Keep the password somewhere safe.'],

        // === ACCESSIBILITY ===
        ['nama' => 'Check Accessibility', 'cat' => 'akses', 'popular' => true, 'desc' => 'A list of issues that make the document hard for screen readers: missing alt text, low contrast, skipped heading levels.', 'langkah' => 'Review → Check Accessibility → select an issue in the pane → follow Recommended Actions.', 'tip' => 'The checker runs in the background while you write and shows a reminder in the status bar.'],
        ['nama' => 'Alt Text', 'cat' => 'akses', 'desc' => 'A short description of a picture, chart, or shape for screen readers.', 'langkah' => 'Right-click the picture → View Alt Text → write one or two sentences.', 'tip' => 'Describe the information, not the look. "Chart: enrolment rises every year since 2022" is more useful than "bar chart".'],
        ['nama' => 'Mark as Decorative', 'cat' => 'akses', 'desc' => 'Decorative images such as lines and borders that screen readers should skip.', 'langkah' => 'Right-click the picture → View Alt Text → select Mark as decorative.'],
        ['nama' => 'Heading Order', 'cat' => 'akses', 'desc' => 'Headings follow their levels without skipping: Heading 1, then Heading 2, then Heading 3.', 'langkah' => 'View → Navigation Pane → check the level of each heading. Change a heading style through Home → Styles.', 'awas' => 'Do not pick Heading 3 only because it is smaller. Change the look through Modify Style and keep the level that matches the structure.'],
        ['nama' => 'Table Header Row', 'cat' => 'akses', 'desc' => 'The first table row is marked as a header so screen readers announce the column names.', 'langkah' => 'Click in the table → Table Design → Header Row. Then Table Layout → Repeat Header Rows.', 'awas' => 'Avoid merged cells, nested tables, and blank rows in data tables. Screen readers lose track of the cell position.'],
        ['nama' => 'Accessible Link Text', 'cat' => 'akses', 'desc' => 'Link text that names its destination, not "click here".', 'langkah' => 'Select the text → Insert → Link → Text to display → ScreenTip (optional) → OK.', 'pintasan' => 'Ctrl+K', 'tip' => 'Use the title of the destination page as the link text.'],
        ['nama' => 'Color Contrast', 'cat' => 'akses', 'desc' => 'Text and background that differ enough to be read, including in high contrast mode.', 'langkah' => 'Review → Check Accessibility → select the color contrast issue → change the font color or shading.', 'awas' => 'Do not convey meaning with color alone, for example "red row = failed". Add text or a symbol.'],
        ['nama' => 'Document Title', 'cat' => 'akses', 'desc' => 'The document title in the file properties, separate from the file name.', 'langkah' => 'File → Info → Properties → Title → type the title.', 'tip' => 'To carry it into a PDF: Save As → PDF → Options → select Document properties.'],
    ],
];
